// src/components/Header.jsx
import React from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import "../styles/main.css";

export default function Header() {
  const location = useLocation();
  const navigate = useNavigate();

  const navItems = [
    { name: "Home", path: "/" },
    { name: "About", path: "/about" },
    { name: "Academics", path: "/academics" },
    { name: "Admissions", path: "/admissions" },
    { name: "Gallery", path: "/gallery" },
    { name: "Contact", path: "/contact" },
  ];

  return (
    <header className="site-header">
      <div className="topbar">
        <div className="top-left">
          <img src="/assets/logo.png" alt="logo" className="logo" />
          <div className="school-meta">
            <div className="school-name">Kendriya Vidyalaya Sector-24 Noida</div>
            <div className="school-sub">
              CBSE Board Affiliated Co-Ed English Medium Senior Secondary School
            </div>
          </div>
        </div>

        <div className="top-right">
          <button
            className="payfee-btn"
            onClick={() => navigate("/parent-fees")}
          >
            💳 Pay Fee
          </button>
          <Link to="/admin/login" className="login-btn">Admin Login</Link>
        </div>
      </div>

      <nav className="main-nav">
        <div className="nav-inner">
          {navItems.map((item) => {
            const active = location.pathname === item.path;
            return (
              <Link
                key={item.name}
                to={item.path}
                className={`nav-item ${active ? "active" : ""}`}
              >
                {item.name}
              </Link>
            );
          })}
        </div>
      </nav>
    </header>
  );
}
